#!/usr/bin/env bash
# Evidence: the Excellence core value is present in all three canonical agent docs.
#
# GENERATED BY THIS SCRIPT — it writes its own transcript via `exec >"$OUT"`, so
# `generated-by` is a fact about the file rather than a claim about who typed it.
# Re-run to reproduce:
#
#   bash docs/evidence/user-profile-excellence-2026-10-22.sh
#
# ⚠ THIS ARTIFACT CARRIES COUNTS AND PHRASE PRESENCE ONLY — NEVER THE PROFILE'S TEXT.
# ~/.hermes/memories/USER.md is personal context about a human, and this repo is PUBLIC:
# committing the profile verbatim would leak PII in the very artifact that documents the
# change. So the checks below print character COUNTS and grep COUNTS, never a line of content.
set -uo pipefail

REPO="${REPO:-$HOME/hermes-cortex}"
PROFILE="${PROFILE:-$HOME/.hermes/memories/USER.md}"
OUT="${OUT:-$REPO/docs/evidence/user-profile-excellence-2026-10-22.txt}"
exec >"$OUT" 2>&1

norm() { sed -e "s|$HOME|~|g" -e $'s/\033\\[[0-9;]*m//g' -e 's/\\033\[[0-9;]*m//g'; }
say()  { printf '%s\n' "$*"; }
sayn() { printf '%s\n' "$*" | norm; }
rule() { printf '%s\n' "────────────────────────────────────────────────────────────"; }

say "Excellence core value across the three canonical agent docs — evidence"
say "captured-at : $(cd "$REPO" && git rev-parse --short HEAD)  (the working tree's revision)"
say "generated-by: docs/evidence/user-profile-excellence-2026-10-22.sh (this file wrote itself)"
say "PII NOTICE  : this transcript prints COUNTS ONLY. The USER profile's content is personal"
say "              and this repository is public, so no line of it appears here."
rule

say ""
say "1. WHY THE THIRD FILE IS NOT WHERE ITS NAME SUGGESTS"
say "   The operator asked for agents.md, claude.md and user.md. 'agents/claude/user.md' as a"
say "   literal path does not exist on this host — searched: the cortex repo, ~/.hermes (incl."
say "   agent-profiles/ and profiles/), ~/.agents, ~/.claude, ~/hc-session2, ~/steadfaste,"
say "   ~/proj, ~/.hermes/hermes-agent, ops/install/harnesses/*, and a home-wide find for"
say "   user.md. The live profile is elsewhere and is HERMES-OWNED:"
say ""
say "     \$ grep -n 'USER.md are Hermes-owned' ops/scripts/cortex-update.sh"
grep -n "USER.md are Hermes-owned" "$REPO/ops/scripts/cortex-update.sh" | norm | sed 's/^/       /'
say ""
say "   ...so it is never deployed, and a repo edit cannot fix it. The sanctioned route is the"
say "   memory tool — which is itself behind the governance lock (measured: the call was refused"
say "   with GOVERNANCE LOCK REQUIRED until this cycle opened)."
rule

say ""
say "2. THE VALUE IS PRESENT IN ALL THREE — by grep COUNT, not by quoting content"
say "   Each line is:  <file>  <count of the word 'Excellence'>  <count of 'core value'>"
for _f in "$REPO/AGENTS.md" "$REPO/CLAUDE.md" "$PROFILE"; do
  _ex=$(grep -c -i "excellence" "$_f" 2>/dev/null || true)
  _cv=$(grep -c -i "core value" "$_f" 2>/dev/null || true)
  sayn "$(printf '     %-46s %s   %s' "$_f" "$_ex" "$_cv")"
done
say ""
say "   The section headings, which are not personal content:"
grep -n -i "^## Excellence" "$REPO/AGENTS.md" "$REPO/CLAUDE.md" 2>/dev/null | norm | sed 's/^/       /'
rule

say ""
say "3. THE PROFILE FIT ITS BUDGET BY CONSOLIDATING, NOT BY TRUNCATING MEANING"
say "   USER.md has a hard 1,375-character budget and sat at 1,373 — 2 characters of headroom —"
say "   so the addition had to be PAID FOR. Three stale details were consolidated: two dated"
say "   parentheticals and one worked example. Counts only, before -> after:"
say ""
say "   MEASURED BEFORE THE UPDATE was applied in this cycle (it cannot be re-measured now —"
say "   the file has already changed), against the LIVE after-value below:"
say ""
sayn "$(printf '     %-46s %s' "$PROFILE (before, this cycle)" "1373 chars — 2 chars of headroom")"
sayn "$(printf '     %-46s %s' "$PROFILE (after, bytes on disk)" "$(wc -c < "$PROFILE" | tr -d ' ') bytes")"
say "     budget                                              1375 chars"
say ""
say "   NOTE the two counts differ BY DESIGN and neither is wrong: the memory tool measures the"
say "   ENTRY TEXT it stores (1,350), while wc -c measures the FILE, which also carries the '§'"
say "   separators between entries. Read the tool's number as the budget figure."
say ""
say "   The memory tool reported: 98% — 1,350/1,375 chars, 7 entries, 4 operations applied."
say "   Nothing was dropped that the profile cannot re-derive: the removed text was example"
say "   detail, not a standing preference."
rule

say ""
say "4. What this capture covers"
say "   UNCOMMITTED at capture time — the committed copy lands one commit after this run."
say "   HEAD at capture: $(cd "$REPO" && git rev-parse --short HEAD)"
(cd "$REPO" && git status --short -- docs/evidence/user-profile-excellence-2026-10-22.sh docs/evidence/user-profile-excellence-2026-10-22.txt | norm | sed 's/^/     /')
say ""
say "   NOTE: the changed FILE (~/.hermes/memories/USER.md) is deliberately absent from the"
say "   range above — it is not in this repository and is never deployed. Its state is evidenced"
say "   by the counts in section 3, which is the strongest claim that can be committed without"
say "   leaking it."
rule
say ""
say "end of evidence"
